class MagicalArtifact {
  constructor(name, powerLevel) {
    this.name = name;
    this.powerLevel = powerLevel;
  }

  getDescription() {
    return `${this.name} (Power: ${this.powerLevel}) is a mysterious artifact.`;
  }
}

class SpellBook extends MagicalArtifact {
  #spells;

  constructor(name, powerLevel, spells) {
    super(name, powerLevel);
    this.#spells = spells;
  }

  castSpell(spellName) {
    if (this.#spells.includes(spellName)) {
      return `Casting ${spellName} from ${this.name}!`;
    } else {
      return `Spell '${spellName}' not found in ${this.name}.`;
    }
  }

  getDescription() {
    return `${super.getDescription()} It contains ${this.#spells.length} spells: ${this.#spells.join(', ')}.`;
  }
}

